#include <item/BookRuntime.hpp>
#include <item/BookSaveFence.hpp>
void HairDyeCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;Check(sources.size()==6,"all six original dyes provided");CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"hair dye owned SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-hair-dye-worker").has_value(),"hair dye actual item worker starts");
    for(unsigned n=0;n<sources.size();++n){
        const ItemOwner owner{ItemOwnerKind::Character,67000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};const auto* profile=catalog->FindCharacterService(sources[n].grant.key);Check(profile && profile->kind==CharacterServiceKind::HairDye && profile->amount==n+1,"source fixed hair appearance matches original dye");
        sql.DirectQuery(("INSERT INTO player.player(id,level,part_hair) VALUES("+std::to_string(owner.id)+",30,5)").c_str());Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"hair dye owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;
        const auto op=[&](){return std::array<std::uint8_t,16>{0xBA,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(++serial)};};
        const auto submit=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"hair dye commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got.has_value(),"hair dye callback completes");return std::move(*got);};
        const auto apply=[&](const ItemCommit& commit){auto got=submit(commit);Check(got.write && got.state,"hair dye write saves and reloads");replay=got.write->replay;state=*got.state;};
        const auto relog=[&](){const auto before=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items==before.items && state.learning==before.learning,"hair and cooldown survive actual new owner session");};
        const auto hair=[&](){auto query=sql.DirectQuery(("SELECT part_hair,typed_book_revision FROM player.player WHERE id="+std::to_string(owner.id)).c_str());Check(query && !query->uiSQLErrno,"actual player hair read succeeds");auto row=mysql_fetch_row(query->Get()->pSQLResult);Check(row && std::stoull(row[1])==state.learning.revision,"player hair and portable snapshot share exact revision");return std::stoul(row[0]);};
        auto spec=sources[n].grant;spec.count=2;const auto ids=runtime::PeekInstanceIds(2);runtime::SpendInstanceIds(2);const auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids);Check(grant.has_value(),"two original non-stackable dyes receive distinct reserved identities");apply(*grant);auto id=ids[0];auto original=state.items[0];
        BookCharacter live;live.hair=CharacterHairState{5,0};live.progression=CharacterProgression{30,0,0,0,0};SkillBookAdmission facts;facts.alive=facts.targetAllowedByRules=true;facts.characterLevel=30;const auto* policy=catalog->FindUsePolicy(catalog->Find(spec.key)->base.usePolicy);while(!(policy->allowedClasses&(1u<<facts.classIndex)))++facts.classIndex;while(!(policy->allowedSexes&(1u<<facts.sexIndex)))++facts.sexIndex;
        const auto output=[&](const std::string& phase,std::uint8_t status=1,std::uint8_t error=255,const CharacterServicePlan* result=nullptr){const auto it=std::ranges::find(state.items,id,&PersistentItem::id);const auto* source=it==state.items.end() ? &original : &*it;const auto write=[&](const char* suffix,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+suffix+".hex");for(auto b:bytes){auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"hair dye actual SQL state packet exported");};write("inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write("details",EncodeTypedItemDetails(*catalog,state.items).value());write("service",EncodeBookRuntime(*catalog,{status,error,123,456,1794787200000ULL,source,&state.learning,live,facts,"",nullptr,{},nullptr,result}).value());};
        output("ready");auto use=MakeCharacterServiceCommit(*catalog,op(),state.fence,state.storages,state.items,state.learning,live,id,facts).value();apply(use.commit);live=state.learning.character;Check(state.items.size()==1 && state.items[0].id==ids[1] && state.items[0].count==1 && live.hair==CharacterHairState{n,static_cast<std::uint16_t>(n ? 30 : 0)} && hair()==n,"original dye and one item debit persist together");output("applied",3,255,&use.result);auto saved=state;apply(use.commit);Check(replay && state.items==saved.items && state.learning==saved.learning,"same dye receipt cannot consume or reset cooldown twice");relog();output("relogged",3,255,&use.result);id=ids[1];original=state.items[0];
        const auto immediate=PrepareCharacterService(*catalog,state.items[0],live,facts);Check(n ? !immediate && immediate.error()==SkillBookError::OnCooldown : immediate.has_value(),"ordinary dye waits and bleach remains allowed immediately");output("immediate",n ? 5 : 1,n ? static_cast<std::uint8_t>(SkillBookError::OnCooldown) : 255);
        facts.characterLevel=32;live.progression->level=32;const auto below=PrepareCharacterService(*catalog,state.items[0],live,facts);Check(n ? !below : below.has_value(),"one level below exact threshold refuses only ordinary dye");output("below",n ? 5 : 1,n ? static_cast<std::uint8_t>(SkillBookError::OnCooldown) : 255);
        facts.characterLevel=33;live.progression->level=33;Check(PrepareCharacterService(*catalog,state.items[0],live,facts).has_value(),"exact three-level boundary admits every color");output("ready2");
        auto stale=MakeCharacterServiceCommit(*catalog,op(),state.fence,state.storages,state.items,state.learning,live,id,facts).value();saved=state;sql.DirectQuery(("UPDATE player.item_owner_fence SET state_revision=state_revision+1 WHERE owner_kind=1 AND owner_id="+std::to_string(owner.id)).c_str());auto refused=submit(stale.commit);Check(!refused.write && refused.state && refused.state->items==saved.items && refused.state->learning==saved.learning,"stale owner fence rolls back hair and last item debit");state=*refused.state;Check(hair()==n,"failed owner CAS cannot change original player hair");output("stale",7);
        const auto mismatch=MakeCharacterServiceCommit(*catalog,op(),state.fence,state.storages,state.items,state.learning,live,id,facts).value();sql.DirectQuery(("UPDATE player.player SET part_hair=999 WHERE id="+std::to_string(owner.id)).c_str());refused=submit(mismatch.commit);Check(!refused.write && refused.state && refused.state->items==state.items && refused.state->learning==state.learning,"exact original hair participant refuses stale appearance without partial debit");state=*refused.state;sql.DirectQuery(("UPDATE player.player SET part_hair="+std::to_string(n)+" WHERE id="+std::to_string(owner.id)).c_str());
        original=state.items[0];const auto last=MakeCharacterServiceCommit(*catalog,op(),state.fence,state.storages,state.items,state.learning,live,id,facts).value();apply(last.commit);live=state.learning.character;Check(state.items.empty() && hair()==n && live.hair->lastDyeLevel==(n ? 33 : 0),"last dye source disappears and independent permanent hair remains");output("last",3,255,&last.result);relog();output("last_relogged",3,255,&last.result);saved=state;apply(use.commit);Check(replay && state.items==saved.items && state.learning==saved.learning && hair()==n,"old dye receipt cannot revive item or rewind later cooldown");
        const auto late=ProtectBookSave("UPDATE player.player SET exp = 0, skill_point = 0, sub_skill_point = 0, horse_skill_point = 0, skill_level = '', level = 1, level_step = 0, stat_point = 0, random_hp = 0, random_sp = 0, alignment = 0, stat_reset_count = 0, part_hair = 555, name = 'late-hair-cache' WHERE id="+std::to_string(owner.id),0,"").value();auto query=sql.DirectQuery(late.c_str());Check(!query->uiSQLErrno && hair()==n,"late legacy full-player cache cannot erase atomic typed hair");
    }
    store.Stop();std::cout<<"SOURCE_HAIR_DYE_WORKER=SUCCESS sources=6 checks="<<checks<<std::endl;
}
